cat > /app/output/index.html <<'HTML'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>MedBook — Find and Book Top Doctors Instantly</title>
  <meta name="description" content="Search providers by specialty, location, and insurance. Read verified reviews and book same-day appointments in minutes with MedBook." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --blue-900: #0b2a5c;
      --blue-700: #0066ff;
      --blue-600: #1a75ff;
      --teal-500: #16b39a;
      --teal-600: #0f9b86;
      --bg: #ffffff;
      --surface: #f4f8ff;
      --surface-2: #eef3fb;
      --text: #14213d;
      --muted: #4d5d80;
      --line: #d9e3f4;
      --shadow: 0 14px 40px rgba(9, 31, 76, 0.12);
      --radius-xl: 24px;
      --radius-lg: 16px;
      --radius-md: 12px;
      --transition: 220ms cubic-bezier(0.2, 0.8, 0.2, 1);
    }

    * { box-sizing: border-box; }

    html, body {
      margin: 0;
      padding: 0;
      background: var(--bg);
      color: var(--text);
      font-family: 'Plus Jakarta Sans', system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
      scroll-behavior: smooth;
    }

    a { color: inherit; text-decoration: none; }

    .container {
      width: min(1120px, calc(100% - 2rem));
      margin-inline: auto;
    }

    .section { padding: 5.5rem 0; }

    .pill {
      display: inline-flex;
      align-items: center;
      gap: .5rem;
      padding: .45rem .8rem;
      border-radius: 999px;
      font-size: .82rem;
      font-weight: 700;
      letter-spacing: .02em;
      color: var(--blue-700);
      background: rgba(0, 102, 255, 0.09);
    }

    h1, h2, h3, p { margin: 0; }

    .heading-xl {
      font-size: clamp(2.2rem, 5vw, 4rem);
      line-height: 1.08;
      letter-spacing: -0.03em;
      font-weight: 800;
    }

    .heading-lg {
      font-size: clamp(1.7rem, 3.4vw, 2.7rem);
      line-height: 1.15;
      letter-spacing: -0.02em;
      font-weight: 800;
    }

    .lede {
      margin-top: 1.25rem;
      color: var(--muted);
      font-size: clamp(1rem, 1.8vw, 1.2rem);
      line-height: 1.7;
      max-width: 62ch;
    }

    .btn {
      border: none;
      border-radius: 12px;
      padding: .9rem 1.2rem;
      font-weight: 700;
      font-size: 1rem;
      cursor: pointer;
      transition: transform var(--transition), box-shadow var(--transition), background-color var(--transition), color var(--transition);
    }

    .btn-primary {
      background: linear-gradient(135deg, var(--teal-500), #23c4a9);
      color: #fff;
      box-shadow: 0 10px 24px rgba(22, 179, 154, .3);
    }

    .btn-primary:hover,
    .btn-primary:focus-visible {
      transform: translateY(-2px);
      background: linear-gradient(135deg, var(--teal-600), #1aa78f);
      box-shadow: 0 14px 28px rgba(15, 155, 134, .35);
      outline: none;
    }

    .btn-ghost {
      background: #fff;
      color: var(--blue-700);
      border: 1px solid var(--line);
    }

    .btn-ghost:hover,
    .btn-ghost:focus-visible {
      transform: translateY(-2px);
      box-shadow: 0 8px 18px rgba(17, 37, 75, .08);
      outline: none;
    }

    header {
      position: sticky;
      top: 0;
      z-index: 50;
      backdrop-filter: saturate(160%) blur(12px);
      background: rgba(255, 255, 255, 0.9);
      border-bottom: 1px solid rgba(217, 227, 244, .8);
    }

    .nav {
      min-height: 78px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: .6rem;
      font-weight: 800;
      font-size: 1.35rem;
      color: var(--blue-900);
    }

    .brand-mark {
      width: 36px;
      height: 36px;
      border-radius: 10px;
      background: linear-gradient(140deg, var(--blue-700), #3f8dff);
      display: grid;
      place-items: center;
      color: #fff;
      font-size: 1rem;
      box-shadow: 0 10px 18px rgba(0, 102, 255, .25);
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 1.2rem;
      color: #2a3b61;
      font-weight: 600;
    }

    .nav-links a {
      padding: .45rem .7rem;
      border-radius: 9px;
      transition: background var(--transition), color var(--transition);
    }

    .nav-links a:hover,
    .nav-links a:focus-visible {
      background: var(--surface);
      color: var(--blue-700);
      outline: none;
    }

    .nav-actions { display: flex; align-items: center; gap: .7rem; }

    .menu-toggle {
      display: none;
      border: 1px solid var(--line);
      border-radius: 10px;
      width: 42px;
      height: 42px;
      background: #fff;
      align-items: center;
      justify-content: center;
      cursor: pointer;
    }

    .menu-toggle span,
    .menu-toggle span::before,
    .menu-toggle span::after {
      display: block;
      width: 18px;
      height: 2px;
      border-radius: 2px;
      background: #1f3260;
      position: relative;
      transition: transform var(--transition), opacity var(--transition);
      content: "";
    }

    .menu-toggle span::before { position: absolute; top: -6px; }
    .menu-toggle span::after { position: absolute; top: 6px; }

    .hero {
      background:
        radial-gradient(circle at 15% 20%, rgba(32, 123, 255, .15), transparent 32%),
        radial-gradient(circle at 86% 10%, rgba(22, 179, 154, .15), transparent 28%),
        linear-gradient(180deg, #f7fbff, #ffffff 76%);
      padding: 4.8rem 0 3.5rem;
    }

    .hero-wrap {
      display: grid;
      grid-template-columns: 1.2fr .9fr;
      gap: 1.5rem 2rem;
      align-items: center;
    }

    .hero-card {
      background: #fff;
      border-radius: var(--radius-xl);
      border: 1px solid #e3ecfb;
      box-shadow: var(--shadow);
      padding: 1.35rem;
      animation: floatIn .8s ease-out both;
    }

    .hero-card h3 {
      font-size: 1.1rem;
      margin-bottom: .9rem;
    }

    .doctor-item {
      display: grid;
      grid-template-columns: auto 1fr auto;
      align-items: center;
      gap: .8rem;
      padding: .75rem;
      border-radius: 12px;
      transition: background var(--transition), transform var(--transition);
    }

    .doctor-item:hover { background: var(--surface); transform: translateX(2px); }

    .avatar {
      width: 42px;
      height: 42px;
      border-radius: 50%;
      display: grid;
      place-items: center;
      color: #fff;
      font-weight: 700;
      font-size: .9rem;
      background: linear-gradient(130deg, #3b88ff, #2fb0ff);
    }

    .doctor-meta small {
      color: var(--muted);
      font-size: .8rem;
    }

    .tag {
      font-size: .75rem;
      font-weight: 700;
      color: #0c826f;
      background: rgba(22, 179, 154, .14);
      border-radius: 999px;
      padding: .35rem .6rem;
      white-space: nowrap;
    }

    .search-wrap {
      margin-top: 2.3rem;
      position: relative;
      z-index: 5;
    }

    .search-panel {
      background: #fff;
      border: 1px solid #deebff;
      border-radius: var(--radius-xl);
      box-shadow: 0 20px 40px rgba(9, 31, 76, .12);
      padding: .75rem;
      display: grid;
      grid-template-columns: 2fr 1.4fr auto;
      gap: .65rem;
      align-items: center;
    }

    .field {
      position: relative;
      border: 1px solid #d9e3f5;
      border-radius: 13px;
      padding: .82rem .9rem;
      display: flex;
      align-items: center;
      gap: .5rem;
      background: #fbfdff;
      transition: border-color var(--transition), box-shadow var(--transition), background var(--transition);
    }

    .field:focus-within {
      border-color: #8cb6ff;
      background: #fff;
      box-shadow: 0 0 0 4px rgba(26, 117, 255, .12);
    }

    .field input {
      border: none;
      outline: none;
      width: 100%;
      font-size: 1rem;
      background: transparent;
      color: var(--text);
      font-family: inherit;
    }

    .field input::placeholder { color: #8090af; }

    .field svg { color: #5a78b0; flex-shrink: 0; }

    .suggestions {
      position: absolute;
      top: calc(100% + .5rem);
      left: 0;
      right: 0;
      background: #fff;
      border: 1px solid #d7e4f8;
      border-radius: 14px;
      box-shadow: 0 18px 28px rgba(8, 28, 70, .13);
      overflow: hidden;
      display: none;
      z-index: 15;
    }

    .suggestions.open { display: block; }

    .suggestion-item {
      width: 100%;
      border: none;
      text-align: left;
      padding: .85rem .95rem;
      background: #fff;
      cursor: pointer;
      font: inherit;
      color: var(--text);
      border-bottom: 1px solid #edf2fb;
    }

    .suggestion-item:last-child { border-bottom: 0; }
    .suggestion-item:hover,
    .suggestion-item:focus-visible {
      background: #f3f8ff;
      color: var(--blue-700);
      outline: none;
    }

    .stats-row {
      margin-top: 1.4rem;
      display: grid;
      gap: .8rem;
      grid-template-columns: repeat(4, minmax(0, 1fr));
    }

    .stat {
      background: #fff;
      border: 1px solid #dce8fa;
      border-radius: 14px;
      padding: 1rem;
      text-align: center;
    }

    .stat b {
      display: block;
      font-size: 1.4rem;
      color: var(--blue-700);
      margin-bottom: .35rem;
    }

    .specialty-grid {
      margin-top: 2rem;
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }

    .specialty-card {
      display: flex;
      align-items: center;
      gap: .75rem;
      background: #fff;
      border: 1px solid #dee8f9;
      border-radius: var(--radius-lg);
      padding: 1rem;
      font-weight: 700;
      color: #1e3768;
      box-shadow: 0 8px 20px rgba(14, 42, 96, .07);
      transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
    }

    .specialty-card:hover,
    .specialty-card:focus-visible {
      transform: translateY(-3px);
      box-shadow: 0 16px 26px rgba(12, 40, 90, .12);
      border-color: #9fc0ff;
      outline: none;
    }

    .icon-badge {
      width: 40px;
      height: 40px;
      border-radius: 12px;
      background: linear-gradient(145deg, #e9f2ff, #f6fbff);
      border: 1px solid #d8e6fb;
      display: grid;
      place-items: center;
      color: var(--blue-700);
      flex-shrink: 0;
    }

    .steps {
      margin-top: 2rem;
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }

    .step {
      background: var(--surface);
      border: 1px solid #dce8fb;
      border-radius: var(--radius-lg);
      padding: 1.3rem;
    }

    .step-num {
      width: 34px;
      height: 34px;
      border-radius: 10px;
      display: grid;
      place-items: center;
      font-weight: 800;
      color: #fff;
      background: linear-gradient(135deg, var(--blue-700), #3f8dff);
      margin-bottom: .9rem;
    }

    .testimonials { background: var(--surface-2); }

    .testimonial-grid {
      margin-top: 2rem;
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }

    .quote {
      background: #fff;
      border-radius: var(--radius-lg);
      border: 1px solid #dbe7f9;
      padding: 1.2rem;
      color: #2b3f69;
      line-height: 1.7;
      box-shadow: 0 8px 20px rgba(13, 39, 87, .07);
    }

    .quote b { display: block; margin-top: .8rem; color: #14213d; }

    .app-panel {
      margin-top: 2rem;
      background: linear-gradient(160deg, #0b2a5c, #0f3d85 55%, #1360c6);
      color: #fff;
      border-radius: var(--radius-xl);
      padding: clamp(1.4rem, 4vw, 2.6rem);
      display: grid;
      gap: 1.5rem;
      grid-template-columns: 1.1fr .9fr;
      align-items: center;
      box-shadow: var(--shadow);
    }

    .feature-list {
      display: grid;
      gap: .7rem;
      margin-top: 1rem;
      font-size: .98rem;
    }

    .feature-list span {
      display: inline-flex;
      align-items: center;
      gap: .55rem;
    }

    .store-buttons {
      display: flex;
      flex-wrap: wrap;
      gap: .7rem;
      margin-top: 1.4rem;
    }

    footer {
      background: #0d1e3f;
      color: #d5deef;
      padding: 3.4rem 0 2.2rem;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1.2rem;
    }

    .footer-col h4 {
      color: #fff;
      margin-bottom: .8rem;
      font-size: .98rem;
    }

    .footer-col a {
      display: block;
      color: #d5deef;
      padding: .22rem 0;
      font-size: .94rem;
    }

    .footer-col a:hover { color: #98beff; }

    .copyright {
      margin-top: 1.5rem;
      padding-top: 1.2rem;
      border-top: 1px solid rgba(218, 230, 252, .16);
      color: #b7c5e1;
      font-size: .92rem;
    }

    .mobile-drawer {
      position: fixed;
      top: 0;
      right: -84%;
      width: min(320px, 84vw);
      height: 100dvh;
      background: #fff;
      border-left: 1px solid var(--line);
      box-shadow: -20px 0 40px rgba(8, 24, 56, .12);
      padding: 1.2rem;
      transition: right var(--transition);
      z-index: 100;
    }

    .mobile-drawer.open { right: 0; }

    .backdrop {
      position: fixed;
      inset: 0;
      background: rgba(3, 14, 35, .36);
      opacity: 0;
      pointer-events: none;
      transition: opacity var(--transition);
      z-index: 90;
    }

    .backdrop.open { opacity: 1; pointer-events: auto; }

    .drawer-links {
      margin-top: 1.6rem;
      display: grid;
      gap: .6rem;
    }

    .drawer-links a {
      padding: .7rem .8rem;
      border-radius: 10px;
      border: 1px solid #e2ebfa;
      font-weight: 600;
      color: #224173;
      background: #f8fbff;
    }

    @keyframes floatIn {
      from { opacity: 0; transform: translateY(16px); }
      to { opacity: 1; transform: translateY(0); }
    }

    @media (max-width: 980px) {
      .hero-wrap,
      .app-panel { grid-template-columns: 1fr; }
      .stats-row { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .specialty-grid,
      .steps,
      .testimonial-grid,
      .footer-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .search-panel { grid-template-columns: 1fr; }
    }

    @media (max-width: 760px) {
      .section { padding: 4.2rem 0; }
      .nav-links,
      .nav-actions .btn { display: none; }
      .menu-toggle { display: inline-flex; }
      .specialty-grid,
      .steps,
      .testimonial-grid,
      .footer-grid,
      .stats-row { grid-template-columns: 1fr; }
      .hero { padding-top: 3.7rem; }
      .hero-card { padding: 1rem; }
      .search-wrap { margin-top: 1.5rem; }
    }
  </style>
</head>
<body>
  <header>
    <div class="container nav">
      <a class="brand" href="index.html" aria-label="MedBook home">
        <span class="brand-mark" aria-hidden="true">✚</span>
        <span>MedBook</span>
      </a>
      <nav class="nav-links" aria-label="Primary">
        <a href="#specialties">Browse</a>
        <a href="#footer-help">Help</a>
        <a href="#">Log In</a>
      </nav>
      <div class="nav-actions">
        <button class="btn btn-primary" type="button">Sign Up</button>
      </div>
      <button class="menu-toggle" id="menuToggle" aria-label="Open mobile menu" aria-expanded="false" aria-controls="mobileDrawer">
        <span></span>
      </button>
    </div>
  </header>

  <aside class="mobile-drawer" id="mobileDrawer" aria-hidden="true">
    <a class="brand" href="index.html"><span class="brand-mark">✚</span><span>MedBook</span></a>
    <div class="drawer-links">
      <a href="#specialties">Browse</a>
      <a href="#">Log In</a>
      <a href="#" style="background:#e9fffa;border-color:#b4eee3;color:#04695b;">Sign Up</a>
    </div>
  </aside>
  <div class="backdrop" id="drawerBackdrop"></div>

  <main>
    <section class="hero">
      <div class="container">
        <div class="hero-wrap">
          <div>
            <span class="pill">Trusted by millions of patients</span>
            <h1 class="heading-xl" style="margin-top:1rem;">Find and book top doctors instantly.</h1>
            <p class="lede">MedBook helps you discover local doctors, dentists, and specialists that match your needs, insurance, and schedule — so you can book same-day care in minutes.</p>
          </div>
          <div class="hero-card" aria-label="Nearby doctor previews">
            <h3>Available near you today</h3>
            <div class="doctor-item">
              <div class="avatar">AS</div>
              <div class="doctor-meta"><strong>Dr. A. Shah</strong><br><small>Primary Care • 4.9 ★</small></div>
              <span class="tag">2:30 PM</span>
            </div>
            <div class="doctor-item">
              <div class="avatar" style="background:linear-gradient(130deg,#33b895,#2b9fff);">DM</div>
              <div class="doctor-meta"><strong>Dr. D. Martin</strong><br><small>Dentist • 4.8 ★</small></div>
              <span class="tag">4:10 PM</span>
            </div>
            <div class="doctor-item">
              <div class="avatar" style="background:linear-gradient(130deg,#5f83ff,#54c1ff);">RL</div>
              <div class="doctor-meta"><strong>Dr. R. Lee</strong><br><small>Dermatologist • 4.9 ★</small></div>
              <span class="tag">5:45 PM</span>
            </div>
          </div>
        </div>

        <div class="search-wrap" id="search">
          <form class="search-panel" id="searchForm" action="search-results.html" method="get">
            <label class="field" for="searchInput">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M11 4a7 7 0 1 1 0 14 7 7 0 0 1 0-14Zm10 17-3.8-3.8" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>
              <input id="searchInput" name="q" autocomplete="off" placeholder="Search specialty, doctor, or condition" aria-label="Search doctors, specialties, or conditions" />
              <div class="suggestions" id="suggestions" role="listbox" aria-label="Search suggestions"></div>
            </label>
            <label class="field" for="locationInput">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M12 21s7-6.2 7-11a7 7 0 0 0-14 0c0 4.8 7 11 7 11Z" stroke="currentColor" stroke-width="2"/><circle cx="12" cy="10" r="2.4" stroke="currentColor" stroke-width="2"/></svg>
              <input id="locationInput" name="location" placeholder="City, ZIP, or neighborhood" aria-label="Location" />
            </label>
            <button class="btn btn-primary" type="submit">Find Doctors</button>
          </form>

          <div class="stats-row" aria-label="Platform statistics">
            <div class="stat"><b>50M+</b><span>Verified patient reviews</span></div>
            <div class="stat"><b>120K+</b><span>Trusted providers nationwide</span></div>
            <div class="stat"><b>Same-day</b><span>Appointments available daily</span></div>
            <div class="stat"><b>$0</b><span>Always free for patients</span></div>
          </div>
        </div>
      </div>
    </section>

    <section class="section" id="specialties">
      <div class="container">
        <span class="pill">Popular specialties</span>
        <h2 class="heading-lg" style="margin-top:1rem;">Browse care by specialty</h2>
        <p class="lede">Choose from popular care categories and jump directly to providers who match your needs.</p>
        <div class="specialty-grid">
          <a class="specialty-card" href="search-results.html?specialty=Primary+Care"><span class="icon-badge">🩺</span>Primary Care</a>
          <a class="specialty-card" href="search-results.html?specialty=Dentist"><span class="icon-badge">🦷</span>Dentist</a>
          <a class="specialty-card" href="search-results.html?specialty=Dermatologist"><span class="icon-badge">✨</span>Dermatologist</a>
          <a class="specialty-card" href="search-results.html?specialty=Psychiatrist"><span class="icon-badge">🧠</span>Psychiatrist</a>
          <a class="specialty-card" href="search-results.html?specialty=Eye+Doctor"><span class="icon-badge">👁️</span>Eye Doctor</a>
          <a class="specialty-card" href="search-results.html?specialty=Orthopedic+Surgeon"><span class="icon-badge">🦴</span>Orthopedic Surgeon</a>
        </div>
      </div>
    </section>

    <section class="section" id="how-it-works" style="background:var(--surface);">
      <div class="container">
        <span class="pill">How it works</span>
        <h2 class="heading-lg" style="margin-top:1rem;">Book your appointment in three easy steps</h2>
        <div class="steps">
          <article class="step"><div class="step-num">1</div><h3>Search providers</h3><p class="lede" style="margin-top:.6rem;font-size:1rem;max-width:100%;">Search for a provider by specialty or condition, then filter by insurance and location.</p></article>
          <article class="step"><div class="step-num">2</div><h3>Pick a convenient time</h3><p class="lede" style="margin-top:.6rem;font-size:1rem;max-width:100%;">Compare real-time availability and choose a time that works with your schedule.</p></article>
          <article class="step"><div class="step-num">3</div><h3>Book instantly</h3><p class="lede" style="margin-top:.6rem;font-size:1rem;max-width:100%;">Confirm online in seconds and receive reminders before your visit.</p></article>
        </div>
      </div>
    </section>

    <section class="section testimonials" id="testimonials">
