  <script>
    const suggestionsData = [
      "Primary Care",
      "Dentist",
      "Dermatologist",
      "Psychiatrist",
      "Eye Doctor",
      "Orthopedic Surgeon",
      "Pediatrician",
      "OB-GYN",
      "Anxiety",
      "Back Pain",
      "Skin Rash",
      "Dr. Emily Carter"
    ];

    const searchInput = document.getElementById('searchInput');
    const suggestions = document.getElementById('suggestions');
    const locationInput = document.getElementById('locationInput');
    const searchForm = document.getElementById('searchForm');

    function renderSuggestions(value) {
      const query = value.trim().toLowerCase();
      if (!query) {
        suggestions.classList.remove('open');
        suggestions.innerHTML = '';
        return;
      }

      const matches = suggestionsData.filter(item => item.toLowerCase().includes(query)).slice(0, 6);
      if (!matches.length) {
        suggestions.classList.remove('open');
        suggestions.innerHTML = '';
        return;
      }

      suggestions.innerHTML = matches
        .map(item => `<button class="suggestion-item" type="button" role="option">${item}</button>`)
        .join('');

      suggestions.classList.add('open');
      suggestions.querySelectorAll('.suggestion-item').forEach(button => {
        button.addEventListener('click', () => {
          searchInput.value = button.textContent;
          suggestions.classList.remove('open');
          searchInput.focus();
        });
      });
    }

    searchInput.addEventListener('input', (event) => renderSuggestions(event.target.value));

    document.addEventListener('click', (event) => {
      if (!event.target.closest('.field')) {
        suggestions.classList.remove('open');
      }
    });

    searchForm.addEventListener('submit', (event) => {
      event.preventDefault();
      const query = encodeURIComponent(searchInput.value.trim() || 'Primary Care');
      const location = encodeURIComponent(locationInput.value.trim() || 'Near me');
      window.location.href = `search-results.html?q=${query}&location=${location}`;
    });

    const menuToggle = document.getElementById('menuToggle');
    const mobileDrawer = document.getElementById('mobileDrawer');
    const drawerBackdrop = document.getElementById('drawerBackdrop');

    function setMenu(open) {
      mobileDrawer.classList.toggle('open', open);
      drawerBackdrop.classList.toggle('open', open);
      menuToggle.setAttribute('aria-expanded', open ? 'true' : 'false');
      mobileDrawer.setAttribute('aria-hidden', open ? 'false' : 'true');
      document.body.style.overflow = open ? 'hidden' : '';
    }

    menuToggle.addEventListener('click', () => {
      const isOpen = mobileDrawer.classList.contains('open');
      setMenu(!isOpen);
    });

    drawerBackdrop.addEventListener('click', () => setMenu(false));
    mobileDrawer.querySelectorAll('a').forEach(link => link.addEventListener('click', () => setMenu(false)));
    window.addEventListener('keydown', (event) => {
      if (event.key === 'Escape') setMenu(false);
    });
  </script>
